import { request } from "undici";

export async function getOrder(id) {
  // new connection every call, no timeouts, body leaked on non-200
  const { statusCode, body } = await request(`https://api.example.com/orders/${id}`);
  if (statusCode !== 200) return null;
  return await body.json();
}

model.en:
Build ONE reused dispatcher with a bounded pool and timeouts, and drain the body on every path:

import { request, Agent } from "undici";
const agent = new Agent({
  connections: 64,               // sized to downstream capacity, not infinity
  connect: { timeout: 2_000 },   // dead-host guard
  headersTimeout: 5_000,         // server accepts but never answers
  bodyTimeout: 10_000,           // stalled body
});
export async function getOrder(id) {
  const { statusCode, body } = await request(
    `https://api.example.com/orders/${id}`, { dispatcher: agent });
  if (statusCode === 200) return await body.json(); // consumes -> connection freed
  await body.dump();             // early-return path still drains -> no leak
  return null;
}

Key moves: (1) construct the Agent ONCE at module scope so all calls share its keep-alive pool (reuse amortises the TCP+TLS handshake); (2) cap connections to the downstream's real capacity; (3) set connect/headers/body timeouts so a hung request can't pin a connection forever; (4) consume the body on success and body.dump() on the non-200 path so the connection always returns to the pool.

model.ru:
Построй ОДИН переиспользуемый диспетчер с ограниченным пулом и таймаутами и вычитывай тело на каждом пути:

import { request, Agent } from "undici";
const agent = new Agent({
  connections: 64,               // под ёмкость downstream, не бесконечность
  connect: { timeout: 2_000 },   // защита от мёртвого хоста
  headersTimeout: 5_000,         // сервер принял, но не отвечает
  bodyTimeout: 10_000,           // зависшее тело
});
export async function getOrder(id) {
  const { statusCode, body } = await request(
    `https://api.example.com/orders/${id}`, { dispatcher: agent });
  if (statusCode === 200) return await body.json(); // вычитал -> соединение свободно
  await body.dump();             // путь раннего выхода тоже вычитывает -> нет утечки
  return null;
}

Ключевое: (1) создать Agent ОДИН раз на уровне модуля, чтобы все вызовы делили его keep-alive пул (переиспользование размазывает хендшейк TCP+TLS); (2) ограничить connections реальной ёмкостью downstream; (3) поставить таймауты connect/headers/body, чтобы зависший запрос не закрепил соединение навсегда; (4) вычитывать тело при успехе и делать body.dump() на ветке не-200, чтобы соединение всегда возвращалось в пул.
